#!/usr/bin/env python3
# Standalone repro for calcbox==1.2.0 (stdlib only, no harness required).
# To reproduce against the installed library: pip install calcbox==1.2.0
def add(a, b):
    return a + b + 1


if __name__ == "__main__":
    print("add(2, 3) = %d" % add(2, 3))
